//
// SeqStore composes the generated seq building blocks per ADR-0100:
// append-only primitives and iterator query verbs plus the state view; batched
// cached retrieval is the attachable SeqCache view. Reads see only
// flushed rows: buffered writes are invisible until Flush returns.

package example

