// The complete CREATE TABLE composed at generation time through the
// ADR-0102 table-clause seam (engine, ORDER BY over the envelope
// roles, indexes, settings — physical names resolved via the IR).
//
//go:embed seq_ddl_clickhouse.out.sql
var seqDDLCreate string

// SeqTableName is the ClickHouse table this store binds — database-
// qualified ("<db>.<table>") when a Database was set at generation.
const SeqTableName = "seq"

// Physical (encoded, quoted) names of the envelope role columns,
// derived from the IR at generation time — exported so consumers can
// address them in ScanOpts.ExtraPredicate and their own SQL.
const (
	SeqColKey       = `"id:id:u64:47::0:"`
	SeqColOrder     = `"id:eid:u64:47::0:"`
	SeqColLifecycle = `"lc:lifecycle:u8:4::0:"`
)

// Arrow output shape the read-access classes expect.
const seqArrowOutputSettings = " SETTINGS output_format_arrow_string_as_string=1, output_format_arrow_low_cardinality_as_dictionary=0"

// seqKeyLiteral renders a Key value as a ClickHouse SQL literal.
func seqKeyLiteral(k uint64) string { return strconv.FormatUint(k, 10) }

// SeqMembershipIds is the membership-id assignment this store was
// generated under: component kind -> membership name -> the uint64 id
// carried in the membership columns. Verbatim-channel memberships embed
// their literal name instead and are absent here.
//
// The ids are declaration-order (1..N per component) and are baked into
// both the component codecs and this store's Scan filters. Nothing on the
// wire records which assignment wrote a row, so rows written under a
// different one decode as ABSENT rather than failing — VerifySchema
// cannot see it. Compare this map against the writer's before pointing a
// regenerated store at existing rows.
var SeqMembershipIds = map[string]map[string]uint64{
	"SeqReading": {},
}

// SeqEntity is the entity bag (ADR-0100 SD5): the envelope plus one option
// per bound component. Arrow-free — safe to hold in the cache.
// Entities returned by cached reads are shared with the cache (and
// every later reader): treat them as immutable.
type SeqEntity struct {
	ID uint64
	// Ord is the Order role value — the caller-supplied, per-key
	// strictly monotonic sequence (ADR-0100 SD2).
	Ord        uint64
	Lifecycle  uint8
	SeqReading option.Option[SeqReading]
}

// Archetype reports which components the entity carries, in schema order.
func (inst *SeqEntity) Archetype() (a []string) {
	if inst.SeqReading.Has {
		a = append(a, "seqReading")
	}
	return
}

// IsTombstone reports whether this row is a state-view deletion
// marker — what the tombstone-blind verbs (Latest, Replay, the
// cache's Get) hand back for a deleted key.
func (inst *SeqEntity) IsTombstone() bool {
	return inst.Lifecycle == recordstore.LifecycleTombstone
}

type SeqStoreConfig struct {
	// Table overrides the ClickHouse table this store binds — the baked
	// SeqTableName — for every statement it issues (DDL, DESCRIBE, INSERT,
	// SELECT). Optionally database-qualified ("<db>.<table>"), unquoted-
	// identifier shape only ([A-Za-z_][A-Za-z0-9_]* per part; the
	// constructor panics otherwise). Empty (the default) binds the baked
	// name. The schema is unchanged — this moves WHERE the rows land, not
	// what they look like — so a scratch table for a test or a per-
	// deployment table needs no regeneration.
	Table string
	// DDLTail is a raw suffix appended verbatim after the composed
	// CREATE TABLE at EnsureTable time — the escape hatch for clauses
	// the generation-time table options (ADR-0102) do not carry.
	DDLTail string
	// Stampers are consulted on every Begin (ADR-0112 M1): each yields
	// surrogate ids stamped as additive HighCardRef memberships onto the
	// entity's attributes. Empty (the default) leaves the store unstamped
	// and behaviour-identical. A stamper must not write to this store.
	// The schema must carry the HighCardRef membership lane, and no
	// component may read that lane back as data — the constructor
	// panics otherwise (ADR-0112 SD2 lane hygiene).
	Stampers []recordstore.ReferenceStamper
	// BestEffortStampFlush relaxes the ADR-0112 SD5 ordered flush: when
	// true, Flush does NOT flush the stampers' dimension stores before its
	// own insert, so a referencing row may become durable ahead of its
	// descriptor fact (resolution self-heals on the dimension's own flush).
	// The default keeps the descriptor durable no later than the row.
	BestEffortStampFlush bool
}

// SeqStore is single-goroutine, like every part it composes. Batched
// cached retrieval is not built in — attach a SeqCache view.
type SeqStore struct {
	exec     recordstore.ExecutorI
	alloc    memory.Allocator
	cfg      SeqStoreConfig
	dml      *lowlevel.InEntitySeqTable
	buffered int
	// pending holds transferred-but-uninserted records after a failed
	// Flush; the next Flush ships them (DiscardPending drops them).
	pending []arrow.RecordBatch
	// dirty tracks locally-written keys between Commit/Delete and the
	// next successful Flush (or DiscardPending). Attached cache views
	// pin these keys until the flush lands (eviction cannot expose the
	// pre-write row) and their fetchers refuse to cache them — the
	// remaining guard for writes the views could not materialize (Raw
	// commits) and for InvalidateAll inside a dirty window.
	dirty map[uint64]struct{}
	// onWrite/onFlush hold the write-through hooks of attached cache
	// views (NewSeqCache registers one pair per view): onWrite populates
	// and pins the committed entity (nil = not materializable or a
	// discarded write — invalidate instead); onFlush releases the pin
	// once the row is durable.
	onWrite []func(uint64, *SeqEntity)
	onFlush []func(uint64)
	// stampers is cfg.Stampers, consulted per Begin (ADR-0112 M1).
	stampers []recordstore.ReferenceStamper
}

// NewSeqStore wires the store. A nil alloc selects the Go allocator.
// Configuring Stampers panics: see the field's doc — this schema
// cannot carry stamps soundly.
func NewSeqStore(exec recordstore.ExecutorI, alloc memory.Allocator, cfg SeqStoreConfig) (inst *SeqStore) {
	if len(cfg.Stampers) > 0 {
		panic("SeqStore: Stampers configured, but no section of the seq schema declares a HighCardRef membership column — stamps would be dropped silently; declare the channel (AddSectionMembership) or drop the stampers")
	}
	if cfg.Table != "" {
		if terr := recordstore.CheckTableRef(cfg.Table); terr != nil {
			panic("SeqStore: " + terr.Error())
		}
	}
	if alloc == nil {
		alloc = memory.NewGoAllocator()
	}
	inst = &SeqStore{exec: exec, alloc: alloc, cfg: cfg, dml: lowlevel.NewInEntitySeqTable(alloc, 64), dirty: make(map[uint64]struct{}), stampers: cfg.Stampers}
	return
}

// tableName is the table reference every statement uses: the configured
// override when set, else the baked SeqTableName.
func (inst *SeqStore) tableName() string {
	if inst.cfg.Table != "" {
		return inst.cfg.Table
	}
	return SeqTableName
}

// applyStampers consults the configured stampers and pushes their surrogate
// ids as ambient HighCardRef memberships onto the open entity (ADR-0112 M1),
// returning the count so Commit/Rollback pop exactly that many.
// context.Background() bounds the interning — the in-memory interner ignores
// it; a ctx-carrying Begin is the future seam for a durable one. No stampers
// means no pushes: inert.
func (inst *SeqStore) applyStampers() (pushed int) {
	for _, s := range inst.stampers {
		for id, err := range s.Current(context.Background()) {
			if err != nil {
				inst.dml.AppendError(err)
				continue
			}
			inst.dml.PushMembershipHighCardRef(uint64(id))
			pushed++
		}
	}
	return
}

// notifyWrite fires the write-through hooks of attached cache views:
// ent is the just-committed entity (the views populate and pin it),
// or nil when the row is not faithfully materializable (Raw commits)
// or a buffered write is being discarded — the views then invalidate
// the key instead.
func (inst *SeqStore) notifyWrite(key uint64, ent *SeqEntity) {
	for _, f := range inst.onWrite {
		f(key, ent)
	}
}

// notifyFlush releases the attached views' dirty-window pins after a
// successful Flush made the key durable.
func (inst *SeqStore) notifyFlush(key uint64) {
	for _, f := range inst.onFlush {
		f(key)
	}
}

// EnsureTable applies the composed CREATE TABLE (plus the DDLTail
// suffix, when configured). Idempotent (CREATE TABLE IF NOT EXISTS).
// The embedded script is issued one statement per Exec — the
// optional CREATE DATABASE, then the CREATE TABLE — because the
// ClickHouse HTTP interface rejects a multi-statement body; under a
// Table override the statements are re-pointed at the override
// (recordstore.ProvisioningStatements: header and database only, the
// column block stays byte-identical).
func (inst *SeqStore) EnsureTable(ctx context.Context) (err error) {
	stmts, err := recordstore.ProvisioningStatements(seqDDLCreate, SeqTableName, inst.cfg.Table)
	if err != nil {
		err = eh.Errorf("ensure table %s: %w", inst.tableName(), err)
		return
	}
	if inst.cfg.DDLTail != "" {
		stmts[len(stmts)-1] += " " + inst.cfg.DDLTail
	}
	for _, sql := range stmts {
		err = inst.exec.Exec(ctx, sql)
		if err != nil {
			err = eh.Errorf("ensure table %s: %w", inst.tableName(), err)
			return
		}
	}
	return
}

// VerifySchema compares the live table's columns — names and order —
// against the generated schema. EnsureTable alone cannot detect drift
// on an existing table (IF NOT EXISTS succeeds against any old shape),
// and the decode is positional, so drift fails late or, for same-typed
// column swaps, silently: run VerifySchema at startup after
// EnsureTable.
//
// It checks the COLUMN contract only. The membership-id contract is not
// checked and cannot be from the schema alone: the ids live in the
// membership columns as ordinary values, and a FAT table legitimately
// carries other kinds' ids beside this store's. Rows written under a
// different id assignment therefore pass VerifySchema and then match
// nothing — every component decodes absent, with no error. Compare
// SeqMembershipIds against the writer's assignment when pointing this
// store at rows it did not write.
//
// What it describes is the reader's own projection — DESCRIBE over
// `SELECT *`, not over the table — because that is what the positional
// decode consumes. DESCRIBE TABLE lists columns SELECT * does not return
// (MATERIALIZED, ALIAS, EPHEMERAL), so a table legitimately carrying one
// beside the generated shape — a derived column added by ALTER after
// EnsureTable, which is how a store gets a skip index over a value its
// leeway attributes only encode — would fail a check whose contract still
// held. Describing the projection also follows the asterisk_include_*
// settings, which decide what SELECT * returns and which nothing here
// pins: under those, a derived column IS in the decode, and this notices
// where a column-kind filter would have blessed the mis-decode.
func (inst *SeqStore) VerifySchema(ctx context.Context) (err error) {
	live := make([]string, 0, 64)
	for rec, rerr := range inst.exec.QueryArrow(ctx, "DESCRIBE (SELECT * FROM "+inst.tableName()+")"+seqArrowOutputSettings) {
		if rerr != nil {
			err = eh.Errorf("describe table %s: %w", inst.tableName(), rerr)
			return
		}
		names, ok := rec.Column(0).(*array.String)
		if !ok {
			err = eh.Errorf("describe table %s: name column is %s, not a string", inst.tableName(), rec.Column(0).DataType())
			rec.Release()
			return
		}
		for i := range int(rec.NumRows()) {
			live = append(live, names.Value(i))
		}
		rec.Release()
	}
	want := lowlevel.CreateSchemaSeqTable().Fields()
	if len(live) != len(want) {
		err = eh.Errorf("schema drift on %s: table has %d columns, the generated schema expects %d — regenerated code against an old table (or vice versa); migrate or regenerate", inst.tableName(), len(live), len(want))
		return
	}
	for i, f := range want {
		if live[i] != f.Name {
			err = eh.Errorf("schema drift on %s: column %d is %q, the generated schema expects %q — the decode is positional; migrate or regenerate", inst.tableName(), i, live[i], f.Name)
			return
		}
	}
	return
}

// SeqEntityBuilder assembles one entity: envelope from Begin, components
// via Add*, direct attribute manipulation via Raw, then Commit.
type SeqEntityBuilder struct {
	store *SeqStore
	key   uint64
	// ent mirrors the typed Add* calls so Commit can write the entity
	// through to attached cache views; raw marks commits that touched
	// the DML directly — those cannot be materialized faithfully and
	// invalidate the key instead.
	ent SeqEntity
	raw bool
	// buf holds each component's section contributions until Commit, so
	// components sharing a section share its frame. It also holds the
	// frame invariants: one contribution per kind, and typed Adds
	// exclusive with Raw (ADR-0183 D4).
	buf dmlruntime.DeferredSectionBuffer
	// pushed counts the ambient memberships Begin pushed via the stampers;
	// Commit/Rollback pop exactly that many (ADR-0112 M1).
	pushed int
}

// endSection closes one section's frame. The buffer calls it once per
// section, after every component that contributed to it has written.
func (inst *SeqEntityBuilder) endSection(section string) error {
	switch section {
	case "measure":
		inst.store.dml.GetSectionMeasure().EndSection()
	}
	return nil
}

// Begin opens one entity with the envelope roles as typed arguments
// (Key, Order) and a live lifecycle.
func (inst *SeqStore) Begin(id uint64, ord uint64) *SeqEntityBuilder {
	lowlevel.InEntitySeqTableBeginEntity(inst.dml)
	lowlevel.InEntitySeqTableSetId(inst.dml, id, ord)
	lowlevel.InEntitySeqTableSetLifecycle(inst.dml, recordstore.LifecycleLive)
	b := &SeqEntityBuilder{store: inst, key: id, ent: SeqEntity{ID: id, Ord: ord, Lifecycle: recordstore.LifecycleLive}}
	b.pushed = inst.applyStampers()
	return b
}

// AddSeqReading contributes the SeqReading component to the open entity.
//
// The attributes are buffered, not written: a section frame closes for
// good, so a component that closed its own sections would shut out the
// next component sharing one. Commit writes them, one frame per section
// in first-seen order (ADR-0183 D4).
//
// A second Add of this component, or an Add on an entity already using
// Raw(), is refused: both used to mark the row un-mirrorable and carry
// on, which made its read-back shape depend on a call the writer had
// probably made by accident.
func (inst *SeqEntityBuilder) AddSeqReading(row SeqReading) *SeqEntityBuilder {
	if err := inst.buf.StartKind("SeqReading"); err != nil {
		inst.store.dml.AppendError(err)
		return inst
	}
	inst.buf.Enqueue("measure", "SeqReading", func() error {
		return seqReadingEmitSectionMeasure(inst.store.dml.GetSectionMeasure(), row)
	})
	inst.ent.SeqReading = option.Some(row)
	return inst
}

// Raw exposes the underlying DML entity for direct attribute
// manipulation within the same entity frame. The type lives in
// internal/lowlevel: callers outside the generated package hold the
// returned value by inference (raw := b.Raw()) and chain its
// methods, but cannot name the type in their own signatures.
func (inst *SeqEntityBuilder) Raw() *lowlevel.InEntitySeqTable {
	if err := inst.buf.MarkRaw(); err != nil {
		inst.store.dml.AppendError(err)
	}
	inst.raw = true // direct DML writes cannot be mirrored into the entity
	return inst.store.dml
}

// Commit finishes the open entity, buffers the row, and writes it
// through to attached cache views: the entity is populated and pinned
// until the store's Flush makes it durable — reads after writes hit
// immediately, and the caching version gate plus the pin make a raced
// refetch of the pre-write row bounce off. A commit that touched
// Raw() cannot be materialized faithfully and invalidates the key
// instead. A failed Commit rolls the frame back — the entity is
// discarded and the store stays usable.
func (inst *SeqEntityBuilder) Commit() (err error) {
	if ferr := inst.buf.Flush(inst.endSection); ferr != nil {
		inst.store.dml.AppendError(ferr) // surfaced by CommitEntity below
	}
	inst.buf.Reset()
	err = lowlevel.InEntitySeqTableCommitEntity(inst.store.dml)
	inst.store.dml.PopMembershipsHighCardRef(inst.pushed) // release Begin's ambient stamps (consumed by the closed attributes)
	if err != nil {
		_ = lowlevel.InEntitySeqTableRollbackEntity(inst.store.dml) // no-op error when no frame is open
		return
	}
	inst.store.buffered++
	inst.store.dirty[inst.key] = struct{}{}
	if inst.raw {
		inst.store.notifyWrite(inst.key, nil)
	} else {
		ent := inst.ent
		inst.store.notifyWrite(inst.key, &ent)
	}
	return
}

// Rollback abandons the open entity frame without committing it;
// already-buffered rows and the store remain usable.
func (inst *SeqEntityBuilder) Rollback() (err error) {
	inst.buf.Reset() // the buffered contributions are abandoned with the frame
	inst.store.dml.PopMembershipsHighCardRef(inst.pushed)
	return lowlevel.InEntitySeqTableRollbackEntity(inst.store.dml)
}

// IngestSeqReading buffers one whole entity per row carrying only the
// SeqReading component, all stamped with ord — rows ship on the next Flush,
// like every write. Keys must be distinct within one call (rows
// share ord, so duplicates would tie on Order): a duplicate returns
// recordstore.ErrDuplicateIngestKey. On any error the rows buffered
// so far remain buffered — Flush ships them, DiscardPending drops
// them.
func (inst *SeqStore) IngestSeqReading(ord uint64, rows []SeqReading) (err error) {
	seen := make(map[uint64]struct{}, len(rows))
	for i := range rows {
		if _, dup := seen[rows[i].ID]; dup {
			err = eh.Errorf("ingest seqReading row %d: %w: key %v", i, recordstore.ErrDuplicateIngestKey, rows[i].ID)
			return
		}
		seen[rows[i].ID] = struct{}{}
		err = inst.Begin(rows[i].ID, ord).AddSeqReading(rows[i]).Commit()
		if err != nil {
			err = eh.Errorf("ingest seqReading row %d: %w", i, err)
			return
		}
	}
	return
}

// Buffered reports the number of committed-but-unflushed rows.
func (inst *SeqStore) Buffered() int { return inst.buffered }

// Flush drains the buffered rows to ClickHouse (Arrow IPC, ADR-0089
// pivot). Rows are durable when Flush returns, engine permitting. On
// insert failure the transferred records are retained and the next
// Flush ships them — Flush is retryable; DiscardPending drops them
// instead. An open (uncommitted) entity frame makes Flush error.
func (inst *SeqStore) Flush(ctx context.Context) (n int, err error) {
	// Ordered flush (ADR-0112 SD5): make the dimension facts this batch
	// references durable before the payload insert, so a referencing row is
	// never durable ahead of its descriptor. On failure nothing is
	// transferred yet — the buffered rows stay and the next Flush retries.
	//
	// This runs BEFORE the nothing-to-do return: a Begin that stamped and
	// then rolled back, or a caller flushing a store whose own rows all
	// went elsewhere, still leaves dimension rows buffered in the stampers,
	// and skipping them here would strand descriptors no later Flush of
	// this store is obliged to ship. Flushing an empty stamper is free.
	if !inst.cfg.BestEffortStampFlush {
		for _, s := range inst.stampers {
			if _, ferr := s.Flush(ctx); ferr != nil {
				err = eh.Errorf("ordered flush of stampers: %w", ferr)
				return
			}
		}
	}
	if inst.buffered == 0 && len(inst.pending) == 0 {
		return
	}
	records, err := lowlevel.InEntitySeqTableTransferRecords(inst.dml, nil)
	if err != nil {
		err = eh.Errorf("transfer records: %w", err)
		return
	}
	records = append(inst.pending, records...)
	inst.pending = nil
	if len(records) > 0 {
		err = inst.exec.InsertArrow(ctx, inst.tableName(), records)
		if err != nil {
			inst.pending = records
			err = eh.Errorf("insert into %s: %w", inst.tableName(), err)
			return
		}
	}
	for _, rec := range records {
		rec.Release()
	}
	n = inst.buffered
	inst.buffered = 0
	for k := range inst.dirty {
		inst.notifyFlush(k) // durable now — release the views' dirty-window pins
	}
	clear(inst.dirty) // flushed — ClickHouse now serves the written state
	return
}

// DiscardPending drops every committed-but-unflushed row: records
// retained by a failed Flush, rows still in the DML builder, and an
// open (uncommitted) entity frame. It gives a failed Flush "never
// happened" semantics — ClickHouse state is the truth afterwards.
// Ambient stamps are cleared with the frame they were pushed for —
// including any pushed through Raw() — so an abandoned builder cannot
// leak its stamps onto later entities.
func (inst *SeqStore) DiscardPending() {
	_ = lowlevel.InEntitySeqTableRollbackEntity(inst.dml) // no-op error when no frame is open
	inst.dml.ClearMembershipsHighCardRef()                // an abandoned Begin's stamps must not outlive its frame
	if records, err := lowlevel.InEntitySeqTableTransferRecords(inst.dml, nil); err == nil {
		for _, rec := range records {
			rec.Release()
		}
	}
	for _, rec := range inst.pending {
		rec.Release()
	}
	inst.pending = nil
	inst.buffered = 0
	for k := range inst.dirty {
		inst.notifyWrite(k, nil) // the cached write never became durable — invalidate
	}
	clear(inst.dirty) // nothing local remains — ClickHouse is the truth
}

// Close discards everything unflushed and releases the store's Arrow
// builder; the store must not be used afterwards. Required for a
// clean shutdown under tracking/checked allocators — the default Go
// allocator needs no Close.
func (inst *SeqStore) Close() {
	inst.DiscardPending()
	lowlevel.InEntitySeqTableReleaseBuilder(inst.dml)
}

// SeqCacheConfig parameterizes an attached read-through cache view.
type SeqCacheConfig struct {
	// Capacity is the L1 capacity in entries, not bytes — budget
	// memory as Capacity × the largest expected entity payload. Zero
	// or negative selects the default (1024).
	Capacity int
	// FetchCriteria are the cache's batch-flush thresholds.
	FetchCriteria caching.FetchCriteria
	// FreshnessTTL enables age-based staleness onset (ADR-0100's
	// external-writer staleness story): entries older than this read
	// as stale — strict reads miss and queue a refetch, accept-stale
	// reads keep serving. Zero disables (staleness stays signal-only).
	FreshnessTTL time.Duration
	// NegativeTTL enables absent-key marking: keys a clean fetch did
	// not return are treated as absent for this long — misses on them
	// neither queue nor suspend work items, so replay loops over keys
	// that do not exist terminate. Zero disables.
	NegativeTTL time.Duration
}

// SeqCache is the batched read-through, write-through KV view over a
// SeqStore (ADR-0100 SD5): misses queue under work items and flush
// as one IN (…) lookup, and local writes populate the view at Commit —
// pinned until the store's Flush makes them durable — so reads after
// writes hit immediately. Admission is version-gated on the entity's
// Order value: a raced refetch of an older row bounces off. Only
// EXTERNAL writers can leave the view stale; they need a caller-
// provided signal: MarkStale / Invalidate / InvalidateAll (a freshness
// TTL option exists on the underlying cache). Raw() commits and
// discarded writes invalidate instead of populating. Like the store
// it wraps, a view is single-goroutine. W is the work-item type (use
// struct{} when the suspend/replay machinery is not needed).
type SeqCache[W comparable] struct {
	st    *SeqStore
	cfg   SeqCacheConfig
	cache *caching.ReadThroughCache[uint64, *SeqEntity, W]
}

// NewSeqCache attaches a read-through, write-through cache view to st,
// registering its write-through and flush hooks with the store. Views
// attach for the store's lifetime — there is no detach.
func NewSeqCache[W comparable](st *SeqStore, cfg SeqCacheConfig) (inst *SeqCache[W]) {
	if cfg.Capacity <= 0 {
		cfg.Capacity = 1024
	}
	inst = &SeqCache[W]{st: st, cfg: cfg}
	inst.rebuild()
	// The hooks close over the view, not the cache instance, keeping
	// them correct if the cache is ever swapped out.
	st.onWrite = append(st.onWrite, func(k uint64, ent *SeqEntity) {
		if ent == nil {
			inst.cache.Delete(k) // not materializable or discarded: invalidate
			return
		}
		inst.cache.AddItem(k, ent) // version-gated write-through
		inst.cache.Pin(k)          // dirty-window latch, released by Flush
	})
	st.onFlush = append(st.onFlush, func(k uint64) { inst.cache.Unpin(k) })
	return
}

func (inst *SeqCache[W]) rebuild() {
	opts := []caching.CacheOption[uint64, *SeqEntity, W]{
		// Admission mirrors the table's newest-row-per-key semantics:
		// the Order value is the entity's monotonic version. The int64
		// reinterpretation preserves the per-key order as long as one
		// key's values share their top bit — which a single writer
		// stream per key (the SD2 contract) gives by construction.
		caching.WithVersioning[uint64, *SeqEntity, W](func(e *SeqEntity) int64 { return int64(e.Ord) }),
	}
	if inst.cfg.FreshnessTTL > 0 {
		opts = append(opts, caching.WithFreshnessTTL[uint64, *SeqEntity, W](inst.cfg.FreshnessTTL))
	}
	if inst.cfg.NegativeTTL > 0 {
		opts = append(opts, caching.WithNegativeCaching[uint64, *SeqEntity, W](inst.cfg.NegativeTTL))
	}
	inst.cache = caching.NewReadThroughCache[uint64, *SeqEntity, W](inst.cfg.Capacity, &seqFetcher{st: inst.st}, inst.cfg.FetchCriteria, opts...)
}

// Get retrieves an entity by Key through the cache; local writes are
// visible immediately (write-through). A miss queues the key for the
// next batch fetch (the caching suspend/replay contract). A miss can
// also mean the batched fetch errored (misses swallow fetch errors;
// the circuit breaker backs off) — GetFetch surfaces the error
// instead, and the store's Latest stays the authoritative check. The
// returned entity is shared with the cache: treat it as immutable.
func (inst *SeqCache[W]) Get(key uint64) (ent *SeqEntity, found bool) {
	return inst.cache.Get(key)
}

// GetFetch is the single-lookup read: the cached entity when present,
// otherwise one immediate batched point fetch — fetch errors surface
// instead of reading as misses, so found=false with err=nil is the
// authoritative absent. A key in the dirty write window that the cache
// could not answer is an error rather than a stale row (see below).
// Prefer Get plus the work-item protocol when batching lookups across a
// frame; the initial miss here also queues the key, so a later batch
// fetch may include it redundantly (harmless).
func (inst *SeqCache[W]) GetFetch(ctx context.Context, key uint64) (ent *SeqEntity, found bool, err error) {
	ent, found = inst.cache.Get(key)
	if found {
		return
	}
	if _, d := inst.st.dirty[key]; d {
		// The key was written locally and is not yet flushed, so ClickHouse
		// still serves the PRE-write row — and the cache miss above means
		// there is no local answer either (a Raw() commit, or a discarded
		// write, invalidates the entry rather than materializing it; an
		// ordinary commit is pinned and would have hit). Returning the
		// pre-write row would be stale, and found=false would assert the
		// authoritative absent this method promises and cannot stand behind
		// here — so say so instead. Flush first, or read through Get plus the
		// work-item protocol, whose fetcher drops dirty keys as a MISS, which
		// queues a refetch rather than claiming absence.
		err = eh.Errorf("get-fetch: key is in the dirty write window — written locally and not yet flushed, and the write was not materializable into the cache; Flush before reading it back")
		return
	}
	ents, err := inst.st.queryEntities(ctx, inst.st.fetchLatestSQL([]uint64{key}))
	if err != nil {
		err = eh.Errorf("get-fetch: %w", err)
		return
	}
	for _, e := range ents {
		if e.ID != key {
			continue
		}
		ent = e
		found = true
		inst.cache.AddItem(key, e)
	}
	return
}

// WorkItem marks the current work item for the cache's miss bookkeeping.
func (inst *SeqCache[W]) WorkItem(w W) iter.Seq[functional.NilIteratorValueType] {
	return inst.cache.WorkItem(w)
}

// IterateReadyWorkItems flushes the queued keys when the fetch criteria
// are met and replays the work items that had misses.
func (inst *SeqCache[W]) IterateReadyWorkItems(ctx context.Context) iter.Seq[W] {
	return inst.cache.IterateReadyWorkItems(ctx)
}

// IterateRestWorkItems forces a fetch of all queued keys and replays
// the pending work items.
func (inst *SeqCache[W]) IterateRestWorkItems(ctx context.Context) iter.Seq[W] {
	return inst.cache.IterateRestWorkItems(ctx)
}

// AdvanceEpoch advances the cache's pinning epoch — call once per
// frame / batch so untouched L1 entries become evictable.
func (inst *SeqCache[W]) AdvanceEpoch() {
	inst.cache.AdvanceEpoch()
}

// MarkStale flags the key's cached entry as stale — the external-writer
// signal: the next strict read misses and queues a refetch, while
// accept-stale reads keep serving the old value until it lands.
func (inst *SeqCache[W]) MarkStale(key uint64) {
	inst.cache.MarkAsStale(key)
}

// MarkStaleIfOlder is the version-carrying external-writer signal:
// it stales the cached entry only if its Order is below order, so a
// redundant signal for a version the view already holds is free —
// the natural sink for an invalidation stream carrying (key, Order).
func (inst *SeqCache[W]) MarkStaleIfOlder(key uint64, order uint64) {
	inst.cache.MarkAsStaleIfOlder(key, int64(order))
}

// Invalidate drops the key's cached entry (L1 and stash).
func (inst *SeqCache[W]) Invalidate(key uint64) {
	inst.cache.Delete(key)
}

// InvalidateAll drops every cached entry — the bulk external-writer
// signal (e.g. after an import). In-flight miss bookkeeping (queued
// keys, pending work items) and the dirty-window pins are dropped
// with it: call between frames, with no suspended work and no
// unflushed local writes (the fetcher's dirty-guard keeps pre-write
// rows out of the cleared cache until the next Flush, at the cost of
// misses on those keys).
func (inst *SeqCache[W]) InvalidateAll() {
	inst.cache.Clear()
}

// GetLive is the cached state-view read: the cache's newest row for
// the key with the tombstone read as absent — exact under this
// process's single writer (local writes invalidate); external writers
// need MarkStale / Invalidate. The store's uncached GetLive stays
// the authoritative read. A miss queues the batch fetch like Get.
func (inst *SeqCache[W]) GetLive(key uint64) (ent *SeqEntity, found bool) {
	ent, found = inst.cache.Get(key)
	if found && ent.IsTombstone() {
		ent = nil
		found = false
	}
	return
}

// GetLiveAcceptStale is the stale-while-revalidate state-view read:
// a stale entry is served immediately (stale=true) while the refetch
// queues in the background — pair with the work-item replay loop.
// Tombstones read as absent; stale then reports whether that verdict
// came from a stale entry.
func (inst *SeqCache[W]) GetLiveAcceptStale(key uint64) (ent *SeqEntity, found bool, stale bool) {
	ent, found, stale = inst.cache.GetAcceptStale(key)
	if found && ent.IsTombstone() {
		ent = nil
		found = false
	}
	return
}

// fetchLatestSQL is the batched newest-row-per-key point lookup shared
// by the cache fetcher and GetFetch.
func (inst *SeqStore) fetchLatestSQL(keys []uint64) string {
	var sb strings.Builder
	sb.WriteString("SELECT * FROM ")
	sb.WriteString(inst.tableName())
	sb.WriteString(" WHERE " + SeqColKey + " IN (")
	for i, k := range keys {
		if i > 0 {
			sb.WriteByte(',')
		}
		sb.WriteString(seqKeyLiteral(k))
	}
	sb.WriteString(") ORDER BY " + SeqColOrder + " DESC LIMIT 1 BY " + SeqColKey)
	sb.WriteString(seqArrowOutputSettings)
	return sb.String()
}

// seqFetcher implements caching.ItemFetcherI for attached cache views —
// an unexported shim so the fetch plumbing stays off the store's
// public method set.
type seqFetcher struct{ st *SeqStore }

var _ caching.ItemFetcherI[uint64, *SeqEntity] = (*seqFetcher)(nil)

// DeterminePartition implements caching.ItemFetcherI. Single partition
// in v1 (one table, one server).
func (inst *seqFetcher) DeterminePartition(key uint64) uint64 { return 0 }

// FetchItemSinglePartition implements caching.ItemFetcherI: one batched
// point lookup per fetch. Duplicate versions collapse newest-first.
// Dirty keys (written locally, not yet flushed) are fetched but not
// cached. With write-through the version gate already rejects the
// pre-write row while the newer entry is resident; this guard is the
// remaining defense for dirty keys the views could NOT materialize
// (Raw commits, discarded writes) and for InvalidateAll inside a
// dirty window, where the cache is cold and the gate has nothing to
// compare against.
func (inst *seqFetcher) FetchItemSinglePartition(ctx context.Context, partition uint64, keys []uint64, target caching.ItemTargetI[uint64, *SeqEntity]) (err error) {
	ents, err := inst.st.queryEntities(ctx, inst.st.fetchLatestSQL(keys))
	if err != nil {
		return
	}
	for _, ent := range ents {
		if _, d := inst.st.dirty[ent.ID]; d {
			continue
		}
		target.AddItem(ent.ID, ent)
	}
	return
}

// Baked ADR-0066 Filter artefacts: rows carrying a conforming
// component. Generated from Plan ⋈ IR; membership ids are literals.
const (
	seqScanSeqReadingFilter = "has(\"tv:measure:lv:lv:y:124:::0::data\", 'reading') AND countEqual(\"tv:measure:lv:lv:y:124:::0::data\", 'reading') = 1"
)

// ScanSeqReading iterates the entities whose rows carry a conforming SeqReading
// component, ordered by (Order, Key) — so entities sharing an Order
// still come out in a fixed sequence. Rows that tie on BOTH (the same
// key written twice at the same Order) are not ordered against each
// other by this clause; the table keeps newest-per-key, so which of
// them survives is the engine's choice, not the scan's.
// opts.ExtraPredicate (trusted raw SQL over the physical columns —
// never untrusted input) further restricts the scan; opts.Limit
// caps the row count. The Filter artefact uses ClickHouse
// built-ins only, so this is a single SELECT — no helper UDFs, no
// multi-statement script (the ExecutorI contract). The sequence is
// single-use; ctx must stay valid until iteration completes; an
// error ends it as a final (nil, err) pair. Scans see only flushed
// rows.
func (inst *SeqStore) ScanSeqReading(ctx context.Context, opts recordstore.ScanOpts) iter.Seq2[*SeqEntity, error] {
	where := seqScanSeqReadingFilter
	if opts.ExtraPredicate != "" {
		where = "(" + where + ") AND (" + opts.ExtraPredicate + ")"
	}
	sql := "SELECT * FROM " + inst.tableName() +
		" WHERE " + where +
		" ORDER BY " + SeqColOrder + " ASC, " + SeqColKey + " ASC"
	if opts.Limit > 0 {
		sql += " LIMIT " + strconv.Itoa(opts.Limit)
	}
	sql += seqArrowOutputSettings
	return inst.iterateEntities(ctx, sql)
}

// Latest returns the newest row for key, tombstone-blind (the raw
// row-level primitive — a deleted key still returns its tombstone
// row; GetLive is the interpreted state-view read). Reads see only
// flushed rows.
func (inst *SeqStore) Latest(ctx context.Context, key uint64) (ent *SeqEntity, found bool, err error) {
	sql := "SELECT * FROM " + inst.tableName() +
		" WHERE " + SeqColKey + " = " + seqKeyLiteral(key) +
		" ORDER BY " + SeqColOrder + " DESC LIMIT 1" + seqArrowOutputSettings
	ents, err := inst.queryEntities(ctx, sql)
	if err != nil || len(ents) == 0 {
		return
	}
	ent = ents[0]
	found = true
	return
}

// Replay iterates the rows for key with the order column >= fromOrder
// in ascending order — the event-replay primitive. A zero fromOrder
// replays everything (0 is the replay-everything bound — a caller
// whose Order values start at 0 must start them at 1 instead);
// opts.To bounds the replay exclusively ("state as of To") and
// opts.Limit caps the row count. The sequence is single-use; ctx
// must stay valid until iteration completes; the query may execute
// at call time or lazily during iteration (buffered in v1 — a
// streaming executor changes nothing visible); an error ends the
// sequence as a final (nil, err) pair. Reads see only flushed rows.
func (inst *SeqStore) Replay(ctx context.Context, key uint64, fromOrder uint64, opts recordstore.ReplayOptsU64) iter.Seq2[*SeqEntity, error] {
	sql := "SELECT * FROM " + inst.tableName() +
		" WHERE " + SeqColKey + " = " + seqKeyLiteral(key)
	if fromOrder > 0 {
		sql += " AND " + SeqColOrder + " >= " + strconv.FormatUint(fromOrder, 10)
	}
	if opts.To > 0 {
		sql += " AND " + SeqColOrder + " < " + strconv.FormatUint(opts.To, 10)
	}
	sql += " ORDER BY " + SeqColOrder + " ASC"
	if opts.Limit > 0 {
		sql += " LIMIT " + strconv.Itoa(opts.Limit)
	}
	sql += seqArrowOutputSettings
	return inst.iterateEntities(ctx, sql)
}

// --- state view (Delete / GetLive; ADR-0100 SD4). Versioned writes
// go through Begin — appending a new version IS the update. ---

// Delete appends a tombstone row for id (no components; lifecycle marks
// the deletion). The tombstone writes through to attached cache views
// like any commit — a versioned deletion, so GetLive reads the key as
// absent immediately.
func (inst *SeqStore) Delete(id uint64, ord uint64) (err error) {
	lowlevel.InEntitySeqTableBeginEntity(inst.dml)
	lowlevel.InEntitySeqTableSetId(inst.dml, id, ord)
	lowlevel.InEntitySeqTableSetLifecycle(inst.dml, recordstore.LifecycleTombstone)
	err = lowlevel.InEntitySeqTableCommitEntity(inst.dml)
	if err != nil {
		_ = lowlevel.InEntitySeqTableRollbackEntity(inst.dml) // discard the failed frame; the store stays usable
		return
	}
	inst.buffered++
	inst.dirty[id] = struct{}{}
	inst.notifyWrite(id, &SeqEntity{ID: id, Ord: ord, Lifecycle: recordstore.LifecycleTombstone})
	return
}

// GetLive is Latest plus tombstone interpretation: newest row wins, a
// tombstone reads as absent — the state-view read (the cache view
// carries the cached twin).
func (inst *SeqStore) GetLive(ctx context.Context, key uint64) (ent *SeqEntity, found bool, err error) {
	ent, found, err = inst.Latest(ctx, key)
	if err != nil || !found {
		return
	}
	if ent.IsTombstone() {
		ent = nil
		found = false
	}
	return
}

// SeqComponentSQL publishes this store's ADR-0066 read-back artefacts —
// the SQL its component definitions generate — for an authoring surface
// to expand (ADR-0189). A host registers it into a componentsql.Registry;
// nothing here self-registers.
//
// Filter is the same constant the Scan verbs use, so the store's own read
// path and the authoring surface cannot disagree about what a conforming
// row is. Projection must not be embedded without Filter — it locates an
// attribute by indexOf and returns the first match, so on a row carrying a
// membership twice it answers plausibly and wrongly (ADR-0066).
//
// The column references are UNQUALIFIED, so a consumer embedding them in a
// join must bind them to SeqTableName itself (ADR-0189 SD6).
var SeqComponentSQL = componentsql.Set{
	Store: "Seq",
	Table: SeqTableName,
	Kinds: map[string]componentsql.Artefacts{
		"SeqReading": {
			Presence:   "has(\"tv:measure:lv:lv:y:124:::0::data\", 'reading')",
			Validator:  "countEqual(\"tv:measure:lv:lv:y:124:::0::data\", 'reading') = 1",
			Filter:     seqScanSeqReadingFilter,
			Projection: "CAST(tuple(\"id:id:u64:47::0:\", LW_VALUE_BY_TAG_EQUAL(\"tv:measure:value:val:u64:4:::0::data\", \"tv:measure:lv:lv:y:124:::0::data\", 'reading', LW_RAGGED_PARENT_IDS(\"tv:measure:lvcard:lvcard:u64:4E:::0::data\"))), 'Tuple(ID UInt64, Value UInt64)')",
		},
	},
}

// --- decode (Arrow → entity bags). ---

// seqSectionReaderI is the uniform slice of the generated read-access
// readers. Column indices stay at their constructor defaults — the
// schema order a SELECT * returns.
type seqSectionReaderI interface {
	LoadFromRecord(raruntime.RecordI) error
	Release()
}

func (inst *SeqStore) queryEntities(ctx context.Context, sql string) (ents []*SeqEntity, err error) {
	for rec, rerr := range inst.exec.QueryArrow(ctx, sql) {
		if rerr != nil {
			err = eh.Errorf("query entities: %w", rerr)
			return
		}
		batch, derr := decodeSeqRecord(rec)
		rec.Release()
		if derr != nil {
			err = derr
			return
		}
		ents = append(ents, batch...)
	}
	return
}

// iterateEntities adapts the buffered query path to the single-use
// iterator contract shared by Replay and the Scan verbs: entities
// yield in query order; an error yields once as (nil, err) and ends
// the sequence.
func (inst *SeqStore) iterateEntities(ctx context.Context, sql string) iter.Seq2[*SeqEntity, error] {
	return func(yield func(*SeqEntity, error) bool) {
		ents, err := inst.queryEntities(ctx, sql)
		if err != nil {
			yield(nil, err)
			return
		}
		for _, ent := range ents {
			if !yield(ent, nil) {
				return
			}
		}
	}
}

// decodeSeqRecord reads one fetched Arrow record into entity bags:
// envelope from the plain readers, components via presence-gated,
// membership-matched reads (fat rows carry optional components — the
// kind-homogeneous helpers cannot decode them).
func decodeSeqRecord(rec arrow.RecordBatch) (ents []*SeqEntity, err error) {
	idR := lowlevel.NewReadAccessSeqTablePlainEntityIdAttributes()
	lcR := lowlevel.NewReadAccessSeqTablePlainEntityLifecycleAttributes()
	measureR := lowlevel.NewReadAccessSeqTableTaggedMeasure()
	readers := []seqSectionReaderI{idR, lcR, measureR}
	for _, r := range readers {
		err = r.LoadFromRecord(rec)
		if err != nil {
			err = eh.Errorf("load seq reader from record: %w", err)
			return
		}
	}
	defer func() {
		for _, r := range readers {
			r.Release()
		}
	}()

	n := idR.ValueId.Len()
	ents = make([]*SeqEntity, 0, n)
	for i := range n {
		ent := &SeqEntity{
			ID:        idR.ValueId.Value(i),
			Ord:       idR.ValueEid.Value(i),
			Lifecycle: lcR.ValueLifecycle.Value(i),
		}
		{
			row, ok, e := seqReadingReadRow(i, measureR.GetAttributes(), measureR.GetMemberships())
			if e != nil {
				err = eh.Errorf("read seqReading component: %w", e)
				return
			}
			if ok {
				row.ID = ent.ID
				ent.SeqReading = option.Some(row)
			}
		}
		ents = append(ents, ent)
	}
	return
}
